import { store, PLATFORM, PROJECTS, PILLARS, storyDebt } from './domain.js';

const $ = (q, root = document) => root.querySelector(q);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const platforms = Array.isArray(PLATFORM) ? PLATFORM.map(p => typeof p === 'string' ? p : p.name || p.platform) : ['LinkedIn','X','Instagram','Threads','TikTok','YouTube','Facebook'];
const nav = [['dashboard','◈','Inicio'],['inbox','↓','Inbox'],['stories','◧','Historias'],['ideas','✧','Ideas'],['content','▤','Contenido'],['calendar','▦','Calendario'],['approvals','✓','Aprobaciones'],['library','▱','Biblioteca'],['mother','◉','Piezas madre'],['metrics','↗','Métricas'],['profile','◎','Perfil'],['settings','⚙','Ajustes']];
const names = {CAPTURED:'Capturado',NEEDS_CONTEXT:'Falta contexto',READY:'Listo',DEVELOPING:'En desarrollo',USED:'Utilizado',ARCHIVED:'Archivado',IDEA:'Idea',DRAFT:'Borrador',APPROVED:'Aprobado',SCHEDULED:'Programado',PUBLISHED:'Publicado',MEASURED:'Medido',REUSABLE:'Reutilizable'};
let view = location.hash.slice(1) || 'dashboard';
let calendarDate = new Date();
let calendarView = 'month';
let selectedProject = '';
let query = '';
let busy = false;
const all = table => store.all(table) || [];
const byId = (table, id) => all(table).find(x => x.id === id);
const project = id => PROJECTS.find(p => p.id === id);
const pillar = id => PILLARS.find(p => p.id === id);
const localDay = date => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Argentina/Buenos_Aires',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(date));
const formatDate = (d, time = false) => d ? new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Buenos_Aires',day:'numeric',month:'short',...(time ? {hour:'2-digit',minute:'2-digit'} : {})}).format(new Date(d)) : 'Sin fecha';
const badge = (status, cls = '') => `<span class="badge ${esc(status?.toLowerCase())} ${cls}">${esc(names[status] || status)}</span>`;
const projectBadge = id => project(id) ? `<span class="project-dot ${project(id).type === 'PRIMARY' ? 'primary' : ''}">${esc(project(id).name)}</span>` : '';
const sourceForStory = s => byId('sources',s.source_id);
const storyForContent = c => {
  if (c.story_id) return byId('stories',c.story_id);
  const mother = c.mother_piece_id ? byId('mother_pieces',c.mother_piece_id) : null;
  const idea = byId('ideas',c.idea_id || mother?.idea_id);
  return byId('stories',idea?.story_id);
};
const debt = () => storyDebt(store);
const filtered = rows => rows.filter(r => (!query || `${r.title} ${r.summary || ''} ${r.text_content || ''}`.toLowerCase().includes(query.toLowerCase())) && (!selectedProject || r.project_id === selectedProject || storyForContent(r)?.project_id === selectedProject));
function iconButton(action, label, text = '↗', data = '') { return `<button class="icon-button" data-action="${action}" ${data} aria-label="${esc(label)}" title="${esc(label)}">${text}</button>`; }
function button(action, label, data = '', cls = '') { return `<button class="button ${cls}" data-action="${action}" ${data}>${label}</button>`; }
function empty(title, desc, action = '', label = '') { return `<div class="empty"><div class="empty-glyph">✧</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action ? button(action,label,'','primary-button') : ''}</div>`; }
function toast(message, error = false) { let el = $('#toast'); if (!el) { el = document.createElement('div'); el.id = 'toast'; el.role = 'status'; document.body.append(el); } el.textContent = message; el.className = error ? 'toast error' : 'toast'; clearTimeout(toast.timer); toast.timer = setTimeout(() => el.remove(),4500); }
function rowActions(action,id,label) { return button(action,label,`data-id="${esc(id)}"`,'small'); }
function titleBlock(kicker,title,description,action = '') { return `<header class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</header>`; }
function filters() { return `<div class="filterbar"><label class="search"><span>⌕</span><input id="search" value="${esc(query)}" placeholder="Buscar en esta vista…" aria-label="Buscar"></label><select id="project-filter" aria-label="Filtrar por proyecto"><option value="">Todos los proyectos</option>${PROJECTS.map(p=>`<option value="${esc(p.id)}" ${selectedProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="muted">Sólo material agregado por vos</span></div>`; }
function metric(label,value,detail,cls='') { return `<article class="metric ${cls}"><div>${label}</div><strong>${value}</strong><small>${detail}</small></article>`; }
function stats() { const variants=all('content_variants'); const cutoff=Date.now()-7*864e5; const weekly=all('sources').filter(s=>new Date(s.captured_at||s.created_at).getTime()>=cutoff).length; const total=Number(store.settings?.experiences||0); return {weekly,capture:total?`${Math.round(Math.min(1,weekly/total)*100)}%`:'—',ready:variants.filter(v=>v.status==='READY').length,approved:variants.filter(v=>v.status==='APPROVED').length,scheduled:variants.filter(v=>v.status==='SCHEDULED').length}; }

function render() {
  if (!sessionStorage.getItem('content-os-local-open')) { renderWelcome(); return; }
  const current=nav.find(n=>n[0]===view)||nav[0];
  const p=stats();
  $('#app').innerHTML = `<div class="app-shell"><aside class="sidebar"><a href="#dashboard" class="brand"><span class="brand-mark">C<span>Ø</span></span><span>CONTENT <b>OS</b><small>Tu trabajo merece una historia.</small></span></a><div class="workspace"><span class="avatar">IC</span><div><strong>${esc(store.profile?.name||'Iván Cristini')}</strong><span>Espacio personal <i>V0.1</i></span></div></div><div class="nav-section">WORKSPACE</div><nav>${nav.map(n=>`<a href="#${n[0]}" class="nav-item ${view===n[0]?'active':''}"><span class="nav-icon">${n[1]}</span>${n[2]}${n[0]==='inbox'&&all('sources').length?`<em>${all('sources').length}</em>`:n[0]==='approvals'&&p.ready?`<em>${p.ready}</em>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-indicator"><span></span>Persistencia local activa</div><small>Los datos quedan en este navegador.<br>Exportá un respaldo desde Ajustes.</small><button data-action="logout" class="text-button">Cerrar espacio ↗</button></div></aside><div class="main-shell"><div class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Abrir navegación">☰</button><div class="breadcrumb">Workspace <span>/</span> <strong>${current[2]}</strong></div><div class="topbar-right"><span class="timezone">Buenos Aires · UTC−3</span><span class="local-badge">LOCAL V0.1</span><button data-action="capture" class="button primary-button small">＋ Capturar</button></div></div><main id="main-content">${renderView()}</main><footer class="main-footer"><span>CONTENT OS · Evidence first</span><span>Capturá lo que construís. Contá lo que importa.</span></footer></div></div><dialog id="editor-dialog" aria-labelledby="modal-title"></dialog>`;
}
function renderWelcome() {
  $('#app').innerHTML = `<main class="welcome"><div class="welcome-grid"></div><div class="welcome-card"><div class="brand welcome-brand"><span class="brand-mark">C<span>Ø</span></span><span>CONTENT <b>OS</b></span></div><div class="eyebrow">DE LO QUE HACÉS A LO QUE CONTÁS</div><h1>Tu construcción diaria.<br>Una narrativa continua.</h1><p>Capturá experiencias reales, desarrollá historias y prepará contenido con intención. SØD, en el centro.</p><div class="welcome-flow"><span>Capturar</span><i>→</i><span>Crear</span><i>→</i><span>Aprobar</span><i>→</i><span>Programar</span></div><button class="button primary-button welcome-cta" data-action="login">Abrir mi espacio local <span>↗</span></button><div class="welcome-note"><strong>Modo local · Sin cuenta ni contraseña</strong><span>Tu información se guarda en este navegador. Este acceso no es autenticación ni sincroniza entre dispositivos. Podés exportar un respaldo cuando quieras.</span></div></div></main>`;
}
function renderView() {
  switch(view) {
    case 'inbox': return renderInbox(); case 'stories':return renderStories();case 'ideas':return renderIdeas();case 'content':return renderContent();case 'calendar':return renderCalendar();case 'approvals':return renderApprovals();case 'profile':return renderProfile();case 'settings':return renderSettings();case 'library':return renderLibrary();case 'mother':return renderMother();case 'metrics':return renderMetrics();default:return renderDashboard();
  }
}
function renderDashboard() {
 const s=stats();const next=all('content_variants').filter(v=>v.status==='SCHEDULED').sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at)).slice(0,4);
 return titleBlock('TU CENTRO EDITORIAL','Lo que construís, cuenta.','Convertí la actividad real en historias que vale la pena compartir.',button('capture','＋ Nueva captura','','primary-button'))+`<div class="focus-banner"><div class="focus-symbol">Ø</div><div><small>PROYECTO PRINCIPAL</small><strong>SØD Ecosystem Global</strong><span>Tu construcción diaria es el punto de partida.</span></div><span class="focus-label">PRIMARY</span></div><section class="metric-grid">${metric('Capture Rate',s.capture,'V0 ESTIMATE · últimos 7 días')}${metric('Story Debt',debt().length,'Historias listas sin contenido','accent')}${metric('Capturas de la semana',s.weekly,'Material registrado en los últimos 7 días')}${metric('En calendario',s.scheduled,'Variantes programadas')}</section><section class="pipeline-strip">${[['Historias activas',all('stories').filter(x=>!['USED','ARCHIVED'].includes(x.status)).length],['Ideas',all('ideas').length],['Listo para revisar',s.ready],['Aprobadas',s.approved]].map(([n,v])=>`<div><span>${n}</span><strong>${v}</strong></div>`).join('')}</section><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h2>Últimas capturas</h2><a href="#inbox">Ver inbox ↗</a></div>${all('sources').length?all('sources').slice().reverse().slice(0,5).map(x=>`<button class="list-row" data-action="source-detail" data-id="${esc(x.id)}"><span class="type-icon">${x.type==='text'?'T':'↥'}</span><div><strong>${esc(x.title)}</strong><small>${projectBadge(x.project_id)} · ${formatDate(x.captured_at||x.created_at)}</small></div>${badge(x.context_status)}</button>`).join(''):empty('La próxima historia empieza acá','Una nota, una foto, una decisión. No hace falta tener el contenido resuelto.','capture','Capturar una experiencia')}</section><section class="panel"><div class="panel-heading"><h2>Deuda narrativa</h2><a href="#stories">Ver historias ↗</a></div>${debt().length?debt().sort((a,b)=>priorityValue(b.importance)-priorityValue(a.importance)).slice(0,4).map(x=>`<div class="list-row"><div><strong>${esc(x.title)}</strong><small>${projectBadge(x.project_id)}</small></div>${rowActions('idea-create',x.id,'Crear idea ↗')}</div>`).join(''):empty('Sin historias pendientes','Las historias listas que aún no generaron contenido aparecerán acá.')}<div class="panel-note">Una historia lista sin una pieza derivada cuenta como Story Debt.</div></section><section class="panel span-two"><div class="panel-heading"><h2>Próximas publicaciones planificadas</h2><a href="#calendar">Abrir calendario ↗</a></div>${next.length?next.map(v=>variantRow(v)).join(''):empty('Tu calendario tiene espacio','Aprobá una variante y asignale fecha. Nada se publica automáticamente.')}</section></div>`;
}
function priorityValue(v) {return {LOW:1,MEDIUM:2,HIGH:3,CRITICAL:4}[v]||Number(v)||0;}
function renderInbox() { const rows=filtered(all('sources')).slice().reverse();return titleBlock('01 / CAPTURAR','Inbox','Guardá el material ahora. La historia puede aparecer después.',button('capture','＋ Capturar','','primary-button'))+filters()+`<div class="capture-hint"><span>↓</span><div><strong>Capturá en menos de un minuto.</strong><span>Texto, archivos o un enlace. Agregá contexto para no perder el significado.</span></div></div>`+(rows.length?`<div class="card-grid">${rows.map(x=>`<article class="content-card"><div class="card-top"><span class="overline">${esc(x.type)}</span>${badge(x.context_status)}</div><button class="card-title" data-action="source-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p>${esc((x.text_content||x.context||'Sin nota de contexto').slice(0,180))}</p><div class="card-meta">${projectBadge(x.project_id)}<span>${formatDate(x.captured_at||x.created_at)}</span></div><div class="card-actions"><span class="muted">${x.privacy==='PRIVATE'?'◈ Privado':'◉ Revisar antes de compartir'}</span>${rowActions('story-create',x.id,'Crear historia ↗')}</div></article>`).join('')}</div>`:empty('Tu inbox está listo','Agregá tu primera experiencia de construcción. El material nunca se publica automáticamente.','capture','＋ Primera captura')); }
function renderStories() {const rows=filtered(all('stories')).slice().reverse();const debtIds=debt().map(s=>s.id);return titleBlock('02 / ENCONTRAR LA HISTORIA','Historias','Escenas, decisiones y aprendizajes con evidencia.',button('story-new','＋ Nueva historia','','primary-button'))+filters()+(rows.length?`<div class="card-grid">${rows.map(x=>`<article class="content-card"><div class="card-top"><span class="overline">${esc(x.story_type||'scene')}</span>${badge(x.status)}</div><button class="card-title" data-action="story-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p>${esc((x.summary||'Sin resumen').slice(0,180))}</p><div class="card-meta">${projectBadge(x.project_id)}<span>${esc(pillar(x.pillar_id)?.name||'Sin pilar')}</span></div><div class="card-actions">${debtIds.includes(x.id)?'<span class="debt-label">● Story Debt</span>':`<span class="muted">${esc(x.importance||'MEDIUM')}</span>`}${rowActions('idea-create',x.id,'Crear idea ↗')}</div></article>`).join('')}</div>`:empty('Las experiencias se vuelven historias','Convertí una captura en una escena, decisión o aprendizaje.','story-new','Crear historia'));}
function renderIdeas(){const rows=filtered(all('ideas')).slice().reverse();return titleBlock('03 / DEFINIR EL ÁNGULO','Ideas','Una tesis clara para cada historia que merece contarse.',button('idea-new','＋ Nueva idea','','primary-button'))+filters()+(rows.length?`<div class="card-grid">${rows.map(x=>`<article class="content-card"><div class="card-top"><span class="overline">POTENCIAL ${esc(x.potential||'MEDIUM')}</span>${badge(x.status)}</div><button class="card-title" data-action="idea-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p>${esc(x.core_thesis||'Sin tesis definida')}</p><div class="card-meta"><span>${esc(x.angle||'Ángulo por definir')}</span><span>${esc(byId('stories',x.story_id)?.title||'Sin historia vinculada')}</span></div><div class="card-actions"><span class="muted">${esc(pillar(x.pillar_id)?.name||'Sin pilar')}</span>${rowActions('content-create',x.id,'Crear contenido ↗')}</div></article>`).join('')}</div>`:empty('Dale una dirección a la historia','La tesis y el ángulo convierten una experiencia en una pieza con intención.','idea-new','Crear idea'));}
function renderContent(){const rows=filtered(all('content_items')).slice().reverse();return titleBlock('04 / PRODUCIR Y ADAPTAR','Contenido','Cada pieza, una intención. Cada plataforma, su propia versión.',button('content-new','＋ Nueva pieza','','primary-button'))+filters()+(rows.length?`<div class="content-list">${rows.map(x=>{const vv=all('content_variants').filter(v=>v.content_item_id===x.id);return `<article class="content-card content-horizontal"><div class="content-body"><div class="card-top">${badge(x.status)}${projectBadge(storyForContent(x)?.project_id)}</div><button class="card-title" data-action="content-detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p>${esc(x.objective||'Objetivo editorial por definir')}</p><div class="platform-list">${vv.map(v=>`<span class="platform-pill">${esc(v.platform)} <i class="status-dot ${esc(v.status.toLowerCase())}"></i></span>`).join('')||'<span class="muted">Sin variantes todavía</span>'}</div></div><div class="horizontal-actions">${rowActions('content-detail',x.id,'Abrir pieza ↗')}${rowActions('variant-create',x.id,'＋ Variante')}</div></article>`;}).join('')}</div>`:empty('El contenido empieza con una idea','Creá una pieza y adaptala a cada red. La aprobación siempre está en tus manos.','content-new','Crear pieza'));}
function variantRow(v){const c=byId('content_items',v.content_item_id);return `<div class="variant-row"><span class="platform-icon">${esc(v.platform.slice(0,2))}</span><div class="variant-info"><button class="inline-title" data-action="variant-edit" data-id="${esc(v.id)}">${esc(c?.title||v.hook||'Variante')}</button><small>${esc(v.platform)} · ${esc(v.format||'Post')}${v.scheduled_at?` · ${formatDate(v.scheduled_at,true)}`:''}</small></div>${badge(v.status)}<div class="variant-actions">${v.status==='READY'?rowActions('approve',v.id,'Aprobar ✓'):''}${v.status==='APPROVED'||v.status==='SCHEDULED'?rowActions('schedule',v.id,v.status==='SCHEDULED'?'Reprogramar':'Programar'):''}${rowActions('variant-edit',v.id,'Editar')}</div></div>`;}
function renderApprovals(){const vv=all('content_variants').filter(v=>['READY','APPROVED','SCHEDULED'].includes(v.status));return titleBlock('05 / CRITERIO HUMANO','Aprobaciones','Revisá cada adaptación antes de darle lugar en el calendario.')+`<div class="info-banner">✓ Aprobar una variante no la publica. Las redes sociales no están conectadas.</div>`+(vv.length?`<section class="panel">${vv.map(variantRow).join('')}</section>`:empty('No hay variantes para revisar','Marcá una variante como “Lista” desde el editor de contenido.'));}
function renderCalendar(){const isWeek=calendarView==='week';const anchor=new Date(calendarDate.getFullYear(),calendarDate.getMonth(),calendarDate.getDate(),12);let start=new Date(anchor);let count;if(isWeek){start.setDate(start.getDate()-((start.getDay()+6)%7));count=7;}else{start=new Date(anchor.getFullYear(),anchor.getMonth(),1,12);start.setDate(start.getDate()-((start.getDay()+6)%7));count=42;}const scheduled=all('content_variants').filter(v=>v.status==='SCHEDULED'&&v.scheduled_at);const monthLabel=new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(anchor);return titleBlock('06 / DARLE CONTINUIDAD','Calendario','Contenido aprobado con fecha. Publicación manual en esta versión.')+`<div class="calendar-toolbar"><div class="calendar-navigation">${button('calendar-prev','‹','','small')}${button('calendar-today','Hoy','','small')}${button('calendar-next','›','','small')}<h2>${esc(monthLabel)}</h2></div><div class="segmented">${button('calendar-month','Mes','',!isWeek?'selected':'')}${button('calendar-week','Semana','',isWeek?'selected':'')}</div></div><div class="calendar-scroll"><div class="calendar ${isWeek?'week':''}"><div class="calendar-weekdays">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const entries=scheduled.filter(v=>localDay(v.scheduled_at)===key);return `<div class="calendar-cell ${d.getMonth()!==anchor.getMonth()&&!isWeek?'outside':''} ${localDay(new Date())===key?'today':''}"><span class="day-number">${d.getDate()}</span>${entries.map(v=>{const c=byId('content_items',v.content_item_id);const story=storyForContent(c||{});return `<button class="calendar-event" data-action="variant-edit" data-id="${esc(v.id)}"><span>${esc(v.platform)} · ${new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Buenos_Aires',hour:'2-digit',minute:'2-digit'}).format(new Date(v.scheduled_at))}</span><strong>${esc(c?.title||v.hook)}</strong><small>${esc(project(story?.project_id)?.name||'Sin proyecto')}</small><small>${esc(pillar(story?.pillar_id)?.name||'Sin pilar')} · Programado</small></button>`;}).join('')}</div>`;}).join('')}</div></div></div><p class="calendar-footnote">Horarios en Buenos Aires (UTC−3). ${scheduled.length} variante${scheduled.length===1?'':'s'} programada${scheduled.length===1?'':'s'}. Hacé clic en una pieza para revisarla o reprogramarla.</p>`;}
function renderProfile(){return titleBlock('IDENTIDAD Y DIRECCIÓN','Tu perfil','Una voz propia. Proyectos claramente separados.')+`<section class="panel profile-identity"><span class="avatar large">IC</span><div><span class="eyebrow">FUNDADOR · ESPACIO PERSONAL</span><h2>${esc(store.profile?.name||'Iván Cristini')}</h2><p>${esc(store.profile?.positioning||'Fundador que construye SØD diariamente y trabaja con IA aplicada, sistemas, proyectos y conexiones estratégicas.')}</p></div></section><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h2>Proyectos</h2></div>${PROJECTS.map(p=>`<div class="list-row"><div><strong>${esc(p.name)}</strong><small>Prioridad editorial ${p.priority}</small></div><span class="badge ${p.type==='PRIMARY'?'approved':''}">${p.type==='PRIMARY'?'Principal':'Independiente'}</span></div>`).join('')}<div class="panel-note">Órbita es un proyecto independiente. No pertenece a SØD.</div></section><section class="panel"><div class="panel-heading"><h2>Pilares editoriales</h2></div>${PILLARS.map((p,i)=>`<div class="list-row"><span class="pillar-number">0${i+1}</span><strong>${esc(p.name)}</strong><span class="muted">${p.priority}</span></div>`).join('')}</section><section class="panel span-two"><div class="panel-heading"><h2>Stack social</h2><span class="muted">Perfiles de referencia · sin conexión API</span></div><div class="social-grid">${socialLinks().map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" class="social-account"><span class="platform-icon">${esc(s.platform.slice(0,2))}</span><div><strong>${s.platform}</strong><small>${esc(s.handle)}</small></div><span>↗</span></a>`).join('')}</div></section></div>`;}
function socialLinks(){return [{platform:'Instagram',handle:'@ivancristini14',url:'https://www.instagram.com/ivancristini14/'},{platform:'TikTok',handle:'@ivan.cristini',url:'https://www.tiktok.com/@ivan.cristini'},{platform:'LinkedIn',handle:'ivancristini',url:'https://www.linkedin.com/in/ivancristini/'},{platform:'X',handle:'@IvanCristini',url:'https://x.com/IvanCristini'},{platform:'Threads',handle:'@ivancristini14',url:'https://www.threads.com/@ivancristini14'},{platform:'YouTube',handle:'@ivancristini3949',url:'https://www.youtube.com/@ivancristini3949'},{platform:'Facebook',handle:'Iván Cristini',url:'https://www.facebook.com/profile.php?id=61566999627436'}];}
function renderSettings(){return titleBlock('TU ESPACIO, TUS DATOS','Ajustes','Persistencia transparente y respaldo bajo tu control.')+`<div class="settings-grid"><section class="panel padded"><h2>Capture Rate · V0 ESTIMATE</h2><p class="muted">Registrá cuántas experiencias relevantes viviste en los últimos 7 días. La estimación compara las capturas registradas con este total declarado; no mide automáticamente tu actividad.</p><form id="experiences-form"><label>Experiencias relevantes de los últimos 7 días<input type="number" min="0" max="100000" name="experiences" value="${Number(store.settings?.experiences||0)}" required></label><button class="button primary-button" type="submit">Guardar estimación</button></form></section><section class="panel padded"><h2>Respaldo y transferencia</h2><p class="muted">El espacio se guarda en este navegador. Exportá tus registros para conservar una copia o trasladarlos. El respaldo JSON incluye texto y metadatos, pero NO incluye los archivos adjuntos. Conservá sus originales aparte.</p><div class="button-row">${button('export','↓ Exportar respaldo','','primary-button')}<label class="button import-label">↑ Importar JSON<input id="import-file" type="file" accept="application/json,.json" hidden></label></div><p class="muted small-text">La importación puede reemplazar el espacio actual. Se pedirá confirmación antes de continuar.</p></section><section class="panel padded"><h2>Conexiones</h2><div class="connection-row"><strong>Supabase</strong><span class="badge">No conectado</span></div><div class="connection-row"><strong>Redes sociales</strong><span class="badge">No conectadas</span></div><div class="connection-row"><strong>IA generativa</strong><span class="badge">No conectada</span></div><p class="muted">El flujo editorial manual funciona completo. No se generan relatos ni se publican materiales automáticamente.</p></section><section class="panel padded"><h2>Privacidad</h2><ul class="privacy-list"><li>Sólo material que agregás intencionalmente.</li><li>Sin acceso a Google Photos ni archivos externos.</li><li>No identificamos personas en fotografías.</li><li>El contenido requiere tu revisión.</li><li>El acceso local no sustituye autenticación.</li></ul></section></div>`;}
function renderLibrary(){const rows=all('sources').filter(s=>s.file_url||s.file_name);return titleBlock('ARCHIVO DE EVIDENCIA','Biblioteca','El material original que acompaña tus historias.')+(rows.length?`<div class="card-grid">${rows.map(s=>`<article class="content-card"><div class="card-top"><span class="overline">${esc(s.type)}</span>${badge(s.context_status)}</div><h3>${esc(s.title)}</h3><p>${esc(s.file_name||'Enlace adjunto')}</p><div class="card-actions">${projectBadge(s.project_id)}${rowActions('source-detail',s.id,'Ver material ↗')}</div></article>`).join('')}</div>`:empty('La evidencia vive acá','Los archivos que adjuntes al inbox estarán disponibles en esta biblioteca.','capture','Adjuntar material'));}
function renderMother(){return titleBlock('UNA FUENTE, MÚLTIPLES DERIVADOS','Piezas madre','Charlas, demos o documentos que pueden sostener varias piezas.',button('mother-create','＋ Pieza madre','','primary-button'))+(all('mother_pieces').length?`<div class="card-grid">${all('mother_pieces').map(m=>`<article class="content-card"><span class="overline">${esc(m.format||'document')}</span><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p>${badge(m.status)}<div class="card-actions"><span class="muted">${all('content_items').filter(c=>c.mother_piece_id===m.id).length} piezas derivadas</span>${rowActions('mother-edit',m.id,'Editar')}</div></article>`).join('')}</div>`:empty('Dale profundidad a tu archivo','Una pieza madre puede originar distintos contenidos sin repetir literalmente la misma historia.','mother-create','Crear pieza madre'));}
function renderMetrics(){return titleBlock('APRENDER SIN INVENTAR RESULTADOS','Métricas','La actividad editorial interna es real. Las métricas de redes aún no están conectadas.')+`<div class="info-banner">↗ Sin conexión a redes: no mostramos alcance, engagement ni seguidores estimados.</div><section class="metric-grid">${metric('Fuentes registradas',all('sources').length,'Datos de tu espacio')}${metric('Historias',all('stories').length,'Experiencias con contexto')}${metric('Piezas de contenido',all('content_items').length,'Piezas editoriales lógicas')}${metric('Variantes',all('content_variants').length,'Adaptaciones por plataforma')}</section><section class="panel"><div class="panel-heading"><h2>Aprendizajes editoriales</h2>${button('learning-create','＋ Registrar aprendizaje','','small')}</div>${all('learnings').length?all('learnings').map(l=>`<div class="list-row"><div><strong>${esc(l.finding)}</strong><small>${esc(l.platform||'General')} · Confianza ${esc(l.confidence||'baja')} · ${esc(l.evidence||'Sin evidencia añadida')}</small></div></div>`).join(''):empty('El criterio también se documenta','Registrá aprendizajes con evidencia. Las conclusiones no se generan automáticamente.')}</section>`;}

const options=(items,value,emptyLabel='Seleccionar…')=>`<option value="">${emptyLabel}</option>`+items.map(x=>{const v=typeof x==='string'?x:x.id;const n=typeof x==='string'?(names[x]||x):x.name||x.title;return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(n)}</option>`;}).join('');
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label>${label}<textarea name="${name}" rows="4" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,items,value='',emptyLabel='Seleccionar…',extra='')=>`<label>${label}<select name="${name}" ${extra}>${options(items,value,emptyLabel)}</select></label>`;
function showModal(title,body,onSave,saveLabel='Guardar',wide=false){const dlg=$('#editor-dialog');dlg.className=wide?'wide':'';dlg.innerHTML=`<form id="modal-form"><div class="modal-heading"><div><span class="eyebrow">CONTENT OS</span><h2 id="modal-title">${esc(title)}</h2></div><button type="button" class="icon-button" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div><p id="form-error" class="form-error" role="alert"></p><div class="modal-footer"><button type="button" class="button" data-action="close-modal">Cerrar</button>${onSave?`<button type="submit" class="button primary-button">${saveLabel}</button>`:''}</div></form>`;dlg.showModal();$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(e.target));const btn=e.submitter;busy=true;if(btn){btn.disabled=true;btn.textContent='Guardando…';}try{await onSave?.(data,e.target);dlg.close();render();}catch(err){$('#form-error').textContent=err.message||'No se pudo guardar. Intentá otra vez.';}finally{busy=false;if(btn){btn.disabled=false;btn.textContent=saveLabel;}}});}
function captureForm(source){const x=source||{};showModal(source?'Editar captura':'Nueva captura',field('Título *','title',x.title,'text','required maxlength="180"')+`<div class="form-grid">${select('Tipo de material','type',['text','photo','video','audio','screenshot','document','url'],x.type||'text','Elegí un tipo','required')}${select('Proyecto *','project_id',PROJECTS,x.project_id||PROJECTS[0]?.id,'Elegí un proyecto','required')}${select('Pilar','pillar_id',PILLARS,x.pillar_id)}${field('Fecha de la experiencia','captured_at',(x.captured_at||new Date().toISOString()).slice(0,10),'date','required')}</div>`+area('Material / contexto','text_content',x.text_content||x.context,'maxlength="20000"')+field('Enlace de referencia','file_url',x.type==='url'?x.file_url||'':'','url')+`<label>Adjuntar archivo <span class="muted">(máximo 20 MB, guardado en este navegador)</span><input type="file" name="attachment"></label><div class="form-grid">${select('Estado de contexto','context_status',['CAPTURED','NEEDS_CONTEXT','READY'],x.context_status||'CAPTURED','Elegí estado','required')}${select('Privacidad','privacy',['PRIVATE','REVIEW'],x.privacy||'PRIVATE','Elegí privacidad','required')}</div><p class="form-help">Si faltan datos o no conocés el contexto de una imagen, elegí “Falta contexto”.</p>`,async(data,form)=>{const file=form.elements.attachment.files[0];let attachment={};if(file?.size){if(file.size>20*1024*1024)throw Error('El archivo supera 20 MB. Usá un enlace o un archivo más pequeño.');attachment=await store.attach(file);}const patch={...data,...attachment,status:data.context_status,captured_at:new Date(`${data.captured_at}T12:00:00-03:00`).toISOString()};delete patch.attachment;if(!file?.size&&source&&source.type!=='url')patch.file_url=source.file_url||'';if(source)await store.update('sources',source.id,patch);else await store.add('sources',patch);toast(source?'Captura actualizada':'Captura guardada. Ya es parte de tu archivo.');},'Guardar captura');}
function storyForm(sourceId,existing){const src=byId('sources',sourceId);const x=existing||{};showModal(existing?'Editar historia':'Crear historia',field('Título *','title',x.title||src?.title,'text','required maxlength="180"')+area('¿Qué pasó y por qué importa? *','summary',x.summary||src?.text_content||'','required maxlength="20000"')+`<div class="form-grid">${select('Fuente','source_id',all('sources').map(s=>({id:s.id,name:s.title})),x.source_id||sourceId)}${select('Proyecto *','project_id',PROJECTS,x.project_id||src?.project_id||PROJECTS[0]?.id,'Elegí proyecto','required')}${select('Pilar','pillar_id',PILLARS,x.pillar_id||src?.pillar_id)}${select('Tipo de historia','story_type',['scene','decision','learning','failure','milestone','meeting','event','experiment','product_update','conversation','backstage'],x.story_type||'scene','Elegí tipo','required')}${select('Importancia','importance',['LOW','MEDIUM','HIGH','CRITICAL'],x.importance||'HIGH','Elegí importancia','required')}${select('Estado','status',['CAPTURED','DEVELOPING','READY','USED','ARCHIVED'],x.status||'READY','Elegí estado','required')}${field('Fecha','event_date',(x.event_date||src?.captured_at||new Date().toISOString()).slice(0,10),'date','required')}</div>`+area('Evidencia y referencias','evidence',x.evidence||src?.file_name||src?.file_url||'','maxlength="10000"'),async data=>{if(data.source_id){const source=byId('sources',data.source_id);if(source?.project_id&&source.project_id!==data.project_id)throw Error('La fuente pertenece a otro proyecto. Mantené separados los proyectos o elegí la fuente correcta.');}if(existing)await store.update('stories',existing.id,data);else await store.add('stories',data);toast('Historia guardada.');},'Guardar historia');}
function ideaForm(storyId,existing){const s=byId('stories',storyId);const x=existing||{};showModal(existing?'Editar idea':'Crear idea',field('Título *','title',x.title||s?.title,'text','required maxlength="180"')+area('Tesis central *','core_thesis',x.core_thesis,'required maxlength="12000"')+area('Ángulo editorial','angle',x.angle,'maxlength="5000"')+`<div class="form-grid">${select('Historia de origen','story_id',all('stories').map(s=>({id:s.id,name:s.title})),x.story_id||storyId)}${select('Pilar','pillar_id',PILLARS,x.pillar_id||s?.pillar_id)}${select('Potencial','potential',['LOW','MEDIUM','HIGH','CRITICAL'],x.potential||'HIGH','Elegí potencial','required')}${select('Estado','status',['IDEA','DEVELOPING','READY','USED','ARCHIVED'],x.status||'READY','Elegí estado','required')}</div>`,async data=>{if(existing)await store.update('ideas',existing.id,data);else await store.add('ideas',data);toast('Idea guardada.');},'Guardar idea');}
function contentForm(ideaId,existing){const idea=byId('ideas',ideaId);const x=existing||{};showModal(existing?'Editar pieza':'Crear pieza de contenido',field('Título *','title',x.title||idea?.title,'text','required maxlength="180"')+area('Objetivo editorial *','objective',x.objective||idea?.core_thesis,'required maxlength="12000"')+`<div class="form-grid">${select('Idea de origen','idea_id',all('ideas').map(i=>({id:i.id,name:i.title})),x.idea_id||ideaId)}${select('Pieza madre (opcional)','mother_piece_id',all('mother_pieces').map(i=>({id:i.id,name:i.title})),x.mother_piece_id)}${select('Prioridad','priority',['LOW','MEDIUM','HIGH','CRITICAL'],x.priority||'HIGH','Elegí prioridad','required')}${select('Estado editorial','status',['DRAFT','READY','ARCHIVED'],['DRAFT','READY','ARCHIVED'].includes(x.status)?x.status:'DRAFT','Elegí estado','required')}</div>`,async data=>{if(existing)await store.update('content_items',existing.id,data);else await store.add('content_items',data);toast('Pieza guardada. Ya podés crear sus variantes.');},'Guardar pieza');}
function contentDetail(id){const c=byId('content_items',id);if(!c)return;showModal(c.title,`<p class="detail-summary">${esc(c.objective)}</p><div class="button-row">${rowActions('content-edit',c.id,'Editar pieza')}${rowActions('variant-create',c.id,'＋ Agregar variante')}</div><h3 class="section-title">Variantes por plataforma</h3>${all('content_variants').filter(v=>v.content_item_id===id).map(variantRow).join('')||'<p class="muted">Todavía no hay adaptaciones. Creá una versión nativa para cada red.</p>'}`,null,'',true);}
function variantForm(contentId,existing){const c=byId('content_items',contentId);const x=existing||{};showModal(existing?'Editar variante':'Nueva variante',`<div class="source-reference">Pieza: ${esc(c?.title||'')}</div><div class="form-grid">${select('Plataforma *','platform',platforms,x.platform||'LinkedIn','Elegí plataforma','required')}${field('Formato *','format',x.format||'Post','text','required maxlength="80"')}</div>`+field('Hook / apertura','hook',x.hook,'text','maxlength="500"')+area('Texto de la variante *','copy',x.copy,'required maxlength="50000"')+field('CTA','cta',x.cta,'text','maxlength="500"')+field('URL del material','media_url',x.media_url,'url')+select('Estado','status',['DRAFT','READY'],['DRAFT','READY'].includes(x.status)?x.status:'DRAFT','Elegí estado','required')+(existing&&['APPROVED','SCHEDULED'].includes(existing.status)?'<p class="form-help">Editar el texto devuelve la variante a borrador y quita su programación. Se requiere una nueva aprobación.</p>':'<p class="form-help">Adaptación manual: no hay IA conectada. No copies literalmente la misma pieza a todas las redes.</p>')+(existing?`<div class="button-row">${existing.status==='READY'?rowActions('approve',existing.id,'Aprobar ✓'):''}${['APPROVED','SCHEDULED'].includes(existing.status)?rowActions('schedule',existing.id,'Programar / cambiar fecha'):''}</div>`:''),async data=>{if(existing){await store.update('content_variants',existing.id,{...data,scheduled_at:null});if(data.status==='READY')await store.update('content_variants',existing.id,{status:'READY'});for(const slot of all('calendar_slots').filter(s=>s.content_variant_id===existing.id))await store.delete('calendar_slots',slot.id);}else await store.add('content_variants',{...data,content_item_id:contentId});toast('Variante guardada.');},'Guardar variante',true);}
function scheduleForm(id){const v=byId('content_variants',id);if(!v)return;if(!['APPROVED','SCHEDULED'].includes(v.status)){toast('Primero aprobá la variante.',true);return;}const date=v.scheduled_at?new Date(new Date(v.scheduled_at).getTime()-3*3600e3).toISOString().slice(0,16):'';showModal('Programar variante',`<p>${esc(v.platform)} · ${esc(byId('content_items',v.content_item_id)?.title)}</p>`+field('Fecha y hora en Buenos Aires (UTC−3) *','scheduled_at',date,'datetime-local','required')+'<p class="form-help">Se agregará al calendario editorial. La publicación en la red será manual.</p>',async data=>{const iso=new Date(`${data.scheduled_at}:00-03:00`).toISOString();await store.schedule(id,iso);toast('Variante programada en el calendario.');},'Programar');}
function sourceDetail(id){const s=byId('sources',id);if(!s)return;const url=s.file_url;let media='';if(url&&/^(https?:|blob:|data:)/i.test(url)){if(s.type==='photo'||s.type==='screenshot')media=`<img class="source-preview" src="${esc(url)}" alt="${esc(s.title)}">`;else if(s.type==='video')media=`<video class="source-preview" src="${esc(url)}" controls></video>`;else if(s.type==='audio')media=`<audio src="${esc(url)}" controls></audio>`;else media=`<a class="button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Abrir material ↗</a>`;}showModal(s.title,`<div class="detail-badges">${badge(s.context_status)}${projectBadge(s.project_id)}</div>${media}<p class="detail-text">${esc(s.text_content||s.context||'Sin contexto adicional.')}</p><p class="muted">${esc(s.file_name||'')} · ${formatDate(s.captured_at||s.created_at,true)}</p><div class="button-row">${rowActions('source-edit',s.id,'Editar captura')}${rowActions('story-create',s.id,'Crear historia ↗')}</div>`,null);}
function storyDetail(id){const s=byId('stories',id);if(!s)return;showModal(s.title,`<div class="detail-badges">${badge(s.status)}${projectBadge(s.project_id)}</div><p class="detail-text">${esc(s.summary)}</p><h3>Evidencia</h3><p class="detail-text">${esc(s.evidence||'Sin evidencia adicional')}</p><p class="muted">Fuente: ${esc(sourceForStory(s)?.title||'Sin fuente vinculada')} · ${esc(pillar(s.pillar_id)?.name||'Sin pilar')}</p><div class="button-row">${rowActions('story-edit',s.id,'Editar historia')}${rowActions('idea-create',s.id,'Crear idea ↗')}</div>`,null);}
function ideaDetail(id){const i=byId('ideas',id);if(!i)return;showModal(i.title,`<p class="detail-text">${esc(i.core_thesis)}</p><h3>Ángulo</h3><p class="detail-text">${esc(i.angle||'Por definir')}</p><p class="muted">Historia: ${esc(byId('stories',i.story_id)?.title||'Sin historia vinculada')}</p><div class="button-row">${rowActions('idea-edit',i.id,'Editar idea')}${rowActions('content-create',i.id,'Crear contenido ↗')}</div>`,null);}
function motherForm(existing){const x=existing||{};showModal(existing?'Editar pieza madre':'Nueva pieza madre',field('Título *','title',x.title,'text','required maxlength="180"')+field('Formato','format',x.format||'Documento','text','required maxlength="80"')+area('Resumen','summary',x.summary,'maxlength="12000"')+select('Fuente','source_id',all('sources').map(s=>({id:s.id,name:s.title})),x.source_id)+select('Idea','idea_id',all('ideas').map(s=>({id:s.id,name:s.title})),x.idea_id)+select('Estado','status',['DRAFT','READY','ARCHIVED'],x.status||'DRAFT','Elegí estado','required'),async data=>{if(existing)await store.update('mother_pieces',existing.id,data);else await store.add('mother_pieces',data);toast('Pieza madre guardada.');});}
function learningForm(){showModal('Registrar aprendizaje',area('Hallazgo *','finding','','required maxlength="10000"')+select('Plataforma','platform',platforms)+select('Pilar','pillar_id',PILLARS)+select('Confianza','confidence',['baja','media','alta'],'baja','Seleccionar','required')+area('Evidencia *','evidence','','required maxlength="10000"'),async data=>{await store.add('learnings',data);toast('Aprendizaje registrado.');});}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{switch(a){case'login':sessionStorage.setItem('content-os-local-open','1');render();break;case'logout':sessionStorage.removeItem('content-os-local-open');render();break;case'menu':$('.sidebar').classList.toggle('mobile-open');break;case'close-modal':$('#editor-dialog')?.close();break;case'capture':captureForm();break;case'source-detail':sourceDetail(id);break;case'source-edit':captureForm(byId('sources',id));break;case'story-new':storyForm();break;case'story-create':storyForm(id);break;case'story-detail':storyDetail(id);break;case'story-edit':storyForm(null,byId('stories',id));break;case'idea-new':ideaForm();break;case'idea-create':ideaForm(id);break;case'idea-detail':ideaDetail(id);break;case'idea-edit':ideaForm(null,byId('ideas',id));break;case'content-new':contentForm();break;case'content-create':contentForm(id);break;case'content-detail':contentDetail(id);break;case'content-edit':contentForm(null,byId('content_items',id));break;case'variant-create':variantForm(id);break;case'variant-edit':{const v=byId('content_variants',id);if(v)variantForm(v.content_item_id,v);break;}case'approve':{const v=byId('content_variants',id);if(!v||v.status!=='READY')throw Error('Sólo podés aprobar variantes listas para revisar.');if(!v.copy?.trim())throw Error('Agregá el texto de la variante antes de aprobar.');await store.update('content_variants',id,{status:'APPROVED'});$('#editor-dialog')?.close();render();toast('Variante aprobada. Ya podés programarla.');break;}case'schedule':scheduleForm(id);break;case'calendar-prev':calendarDate=calendarView==='month'?new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1):new Date(calendarDate.getTime()-7*864e5);render();break;case'calendar-next':calendarDate=calendarView==='month'?new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1):new Date(calendarDate.getTime()+7*864e5);render();break;case'calendar-today':calendarDate=new Date();render();break;case'calendar-month':calendarView='month';render();break;case'calendar-week':calendarView='week';render();break;case'mother-create':motherForm();break;case'mother-edit':motherForm(byId('mother_pieces',id));break;case'learning-create':learningForm();break;case'export':{const data=await store.export();const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=`content-os-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Respaldo exportado. Guardalo en un lugar seguro.');break;}}}catch(err){toast(err.message||'No se pudo completar la acción.',true);}});
document.addEventListener('change',async e=>{if(e.target.id==='project-filter'){selectedProject=e.target.value;render();}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;if(!confirm('¿Importar este respaldo? Puede reemplazar los datos actuales. Exportá una copia antes de continuar.'))return;try{if(f.size>100*1024*1024)throw Error('El respaldo supera 100 MB.');await store.import(await f.text());render();toast('Respaldo importado.');}catch(err){toast(err.message||'El respaldo no es válido.',true);}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const focus=e.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(focus,focus);}});
document.addEventListener('submit',async e=>{if(e.target.id==='experiences-form'){e.preventDefault();try{const experiences=Number(new FormData(e.target).get('experiences'));await store.setSettings({experiences});render();toast('Estimación actualizada.');}catch(err){toast(err.message,true);}}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'dashboard';query='';selectedProject='';render();window.scrollTo(0,0);});
try{await store.init();render();}catch(err){$('#app').innerHTML=`<main class="welcome"><section class="welcome-card"><h1>No pudimos abrir tu espacio.</h1><p>${esc(err.message)}</p><p>Verificá que el navegador permita almacenamiento local y recargá la página.</p><button class="button primary-button" onclick="location.reload()">Reintentar</button></section></main>`;}
